function checkpoint(){history.push({outputs:clone(outputs),activeId,selectedId,selectedIds:[...selectedIds],sources:clone(sources),baseBackground,solidBackgroundChosen,backgroundSource:clone(backgroundSource),reference,formats:clone(FORMATS),checked:chosenFormats(),safeGuides:$('safeGuides').checked,view:$('editor').hidden?'grid':'edit',campaign:$('campaign').value});if(history.length>30)history.shift();$('undo').disabled=false}
