function escapeText(text){return String(text).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function formatOptions(checked=FORMATS.map(f=>f.id)){ $('formats').innerHTML=FORMATS.map(f=>`<div class="format-entry"><label class="format-option"><input type="checkbox" value="${f.id}" ${checked.includes(f.id)?'checked':''}><span class="format-icon" style="width:${f.w>f.h?20:13}px;height:${f.w>f.h?12:18}px"></span><span class="format-label">${escapeText(f.name)}<small>${f.w} × ${f.h} px</small></span><span class="format-badge">${f.group}</span></label><button class="format-remove" type="button" data-remove-format="${f.id}" aria-label="Excluir formato ${escapeText(f.name)}" title="Excluir formato">×</button></div>`).join('');$('formats').onchange=()=>{$('formatCount').textContent=chosenFormats().length;globalThis.SplitFormatProfiles?.render();globalThis.SplitProjects?.changed()};$('formatCount').textContent=checked.length;globalThis.SplitProjects?.changed();for(const button of $('formats').querySelectorAll('button[data-remove-format]'))button.onclick=()=>removeFormat(button.dataset.removeFormat);globalThis.SplitFormatProfiles?.render();}
function validateDimensions(w,h){if(!Number.isInteger(w)||!Number.isInteger(h)||w<32||h<32||w>4096||h>4096||w*h>16000000)throw Error('Use dimensões inteiras de 32 a 4096 px, com até 16 megapixels.');}
function addCustomFormat(w,h){validateDimensions(w,h);const duplicate=FORMATS.find(f=>f.w===w&&f.h===h);if(duplicate){const chosen=chosenFormats();formatOptions([...new Set([...chosen,duplicate.id])]);toast('Este tamanho já existe e foi selecionado.');return duplicate.id}checkpoint();const checked=chosenFormats(),f={id:`custom-${++customSequence}`,name:`Personalizado ${w} × ${h}`,w,h,group:'CUSTOM',custom:true};FORMATS.push(f);formatOptions([...checked,f.id]);toast('Tamanho adicionado. Clique em Gerar composições.');return f.id}
function removeFormat(id){const i=FORMATS.findIndex(f=>f.id===id);if(i<0)return;checkpoint();const checked=chosenFormats().filter(x=>x!==id);FORMATS.splice(i,1);outputs=outputs.filter(o=>o.id!==id);if(activeId===id){activeId=outputs[0]?.id||null;selectedId=null}formatOptions(checked);refresh();toast('Formato excluído. As demais composições foram preservadas.');}
