let fontsPromise;function ensureFonts(){if(!document.fonts)return Promise.resolve();if(!fontsPromise)fontsPromise=Promise.all([300,400,500,600,700,800,900].map(w=>document.fonts.load(`${w} 16px Figtree`))).then(results=>{if(results.some(r=>!r.length))throw Error('Figtree não carregou. Recarregue a página antes de exportar.');}).catch(e=>{fontsPromise=null;throw e});return fontsPromise;}
let layoutMeasureContext;
