async function generate(){await globalThis.SplitMemory?.readGeneral();try{await ensureFonts()}catch(e){toast(e.message);return;}const ids=chosenFormats();if(!sources.length&&!backgroundSource&&!solidBackgroundChosen){toast('Escolha uma cor de fundo ou adicione uma imagem ou elemento.');return}if(!ids.length){toast('Escolha ao menos um formato de saída.');return}checkpoint();outputs=FORMATS.filter(f=>ids.includes(f.id)).map(f=>{const existing=outputs.find(o=>o.id===f.id);if(existing&&globalThis.SplitBlueprint?.enabled()&&SplitBlueprint.itemMode?.()){const prior=existing.layers;existing.layers=[...sources.map(source=>({...source,...prior.find(item=>item.id===source.id)})),...prior.filter(item=>item.blueprintSourceId&&item.id!==item.blueprintSourceId)];}return existing?arrangeOutput(existing,false,true):makeOutput(f)});activeId=outputs.some(o=>o.id===activeId)?activeId:outputs[0].id;selectedId=null;globalThis.SplitMemory?.record('generation',outputs,{images,planned:!!globalThis.SplitBlueprint?.enabled()});refresh();setView('grid');toast(outputs.some(o=>o.layers.some(l=>l.layoutConflict)||o.planWarnings?.length)?'Composições geradas com avisos. Confira áreas sobrepostas, camadas bloqueadas e conteúdo disponível.':`${outputs.length} composições prontas para ajustar.`)}
