function addText(role='text'){addSource({id:uid(),type:role==='cta'?'cta':'text',role,name:role==='cta'?'Chamada para ação':'Texto',text:role==='cta'?'Saiba mais':'Sua mensagem aqui',color:role==='cta'?'#ffffff':'#172226',fill:'#e8502e',cornerRadius:role==='cta'?0:undefined,align:role==='cta'?'center':'left',weight:700})}
async function readImage(file){if(!file)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Use uma imagem PNG, JPG ou WebP.');if(file.size>20*1024*1024)throw Error('A imagem deve ter até 20 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(img.width*img.height>50000000)throw Error('Use uma imagem com até 50 megapixels.');return {img,url,name:file.name,file}}catch(e){URL.revokeObjectURL(url);throw e}}
async function uploadElement(file,role=elementRole){try{const data=await readImage(file);if(!data)return;const id=uid();images.set(id,data.img);if(data.file)assetFiles.set(id,data.file);const label={logo:'Logo',offer:'Oferta',cta:'Botão',text:'Texto (imagem)'}[role];addSource({id,type:'image',role,name:label?`${label} · ${data.name}`:data.name,asset:id,fit:'contain'});toast(`${label||'Imagem'} adicionada. A proporção e a transparência são preservadas.`);}catch(e){toast(e.message)}}
function fitImage(ctx,img,x,y,w,h,mode,focusX=.5,focusY=.5){const ratio=mode==='cover'?Math.max(w/img.width,h/img.height):Math.min(w/img.width,h/img.height);const dw=img.width*ratio,dh=img.height*ratio;ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.drawImage(img,x+(w-dw)*focusX,y+(h-dh)*focusY,dw,dh);ctx.restore()}
