function backgroundMethod(f){return{texture:'Síntese de textura',geometry:'Reconstrução geométrica',inpaint:'OpenCV',edge:'OpenCV'}[SplitBackground.get(f)?.method]||({texture:'Síntese de textura',geometry:'Reconstrução geométrica',opencv:'OpenCV'}[f.background?.mode]||'Reconstrução automática');}
function paintBackgroundBase(ctx,f){const bg=f.background,img=bg&&images.get(bg.asset);if(!img)return;const p=backgroundPlan(img,f.w,f.h,bg.mode),fx=(bg.focusX??50)/100,fy=(bg.focusY??50)/100;if(reconstructedMode(p.mode)){const cached=SplitBackground.get(f);SplitFeather.paint(ctx,img,f,cached?.canvas,fx,fy);return;}if(p.mode==='extend'){const sc=Math.min(1,900/Math.max(f.w,f.h)),cw=Math.max(1,Math.round(f.w*sc)),ch=Math.max(1,Math.round(f.h*sc)),key=[bg.asset,cw,ch,fx,fy,f.bg].join(':');let blurred=backgroundCache.get(key);if(!blurred){blurred=document.createElement('canvas');blurred.width=cw;blurred.height=ch;const bc=blurred.getContext('2d');bc.fillStyle=f.bg;bc.fillRect(0,0,cw,ch);const blur=Math.max(6,Math.min(cw,ch)*.045),pad=blur*3;bc.filter=`blur(${blur}px)`;fitImage(bc,img,-pad,-pad,cw+pad*2,ch+pad*2,'cover',fx,fy);bc.filter='none';if(backgroundCache.size>=12)backgroundCache.delete(backgroundCache.keys().next().value);backgroundCache.set(key,blurred)}SplitFeather.paint(ctx,img,f,blurred,fx,fy);}else if(p.mode==='contain')SplitFeather.paint(ctx,img,f,null,fx,fy);else fitImage(ctx,img,0,0,f.w,f.h,p.mode,fx,fy);}
