async function uploadBackground(file){try{const data=await readImage(file);if(!data)return;checkpoint();const id=uid();images.set(id,data.img);if(data.file)assetFiles.set(id,data.file);backgroundSource={asset:id,name:data.name,mode:'auto',focusX:50,focusY:50,feather:12,zoom:100};for(const out of outputs)out.background=clone(backgroundSource);refresh();toast('Fundo adicionado. A adaptação automática será aplicada a cada tamanho.')}catch(e){toast(e.message)}}
async function prepareBackground(f,retry=false){const bg=f.background,img=bg&&images.get(bg.asset);if(!img||!reconstructedMode(backgroundPlan(img,f.w,f.h,bg.mode).mode))return;return SplitBackground.prepare(f,img,retry);}
function updateBackground(fn){const f=current();if(!f?.background)return;checkpoint();fn(f.background);renderEditor();}
function renderBackgroundControls(){const f=current(),bg=f?.background;$('backgroundControls').hidden=!bg;$('retryBackground').hidden=true;if(!bg)return;$('backgroundMode').value=bg.mode;globalThis.SplitBackgroundMenu?.sync();$('backgroundZoom').value=bg.zoom??100;$('backgroundZoomValue').textContent=`${bg.zoom??100}%`;$('resetBackgroundZoom').disabled=(bg.zoom??100)===100;$('backgroundFocusX').value=bg.focusX??50;$('backgroundFocusY').value=bg.focusY??50;const img=images.get(bg.asset);if(!img)return;const p=backgroundPlan(img,f.w,f.h,bg.mode);$('backgroundFeatherField').hidden=p.mode==='cover';$('backgroundFeather').value=bg.feather??12;$('backgroundFeatherValue').textContent=`${bg.feather??12}%`;let notice;if(reconstructedMode(p.mode)){const status=SplitBackground.status(f);$('retryBackground').hidden=status!=='error';const method=SplitBackground.get(f)?.method;notice=status==='ready'?`${backgroundMethod(f)}: ${method==='texture'?'pequenos trechos do fundo foram combinados com cortes de sobreposição. Texturas podem repetir detalhes.':method==='geometry'?'cores, gradientes e contornos simples foram reconstruídos.': 'bordas estendidas com suavidade progressiva e pequenos espaços reparados.'} O centro da imagem é preservado e as bordas têm transição suave; nenhum modelo de IA é usado.`:status==='error'?'Não foi possível processar o fundo. Tente novamente ou escolha outro modo antes de exportar.':`${backgroundMethod(f)} · preparando o fundo…`}else notice=p.mode==='extend'?'A imagem inteira é preservada. As áreas excedentes recebem uma cópia desfocada do próprio fundo.':p.mode==='cover'?`Fundo preenchido com recorte de aproximadamente ${p.cropped}% da imagem. Ajuste o foco para escolher a área visível.`:'A imagem inteira é preservada; as áreas excedentes usam a cor de fundo.';$('backgroundNotice').textContent=notice+((bg.zoom??100)>100?` Zoom de ${bg.zoom}% aplicado; áreas fora da peça são recortadas.`:'');}
function wrapText(ctx,text,maxWidth){const lines=[];for(const paragraph of text.split('\n')){if(!paragraph){lines.push('');continue}let line='';for(const word of paragraph.split(/\s+/)){if(ctx.measureText(word).width>maxWidth){if(line){lines.push(line);line=''}let part='';for(const char of Array.from(word)){if(part&&ctx.measureText(part+char).width>maxWidth){lines.push(part);part=char}else part+=char}line=part;}else if(line&&ctx.measureText(line+' '+word).width>maxWidth){lines.push(line);line=word}else line+=(line?' ':'')+word}lines.push(line)}return lines}
function textMetrics(ctx,l,f){const w=l.w*f.w,h=l.h*f.h,pad=['cta','offer'].includes(l.type)?Math.min(w*.06,h*.15):0;let size=l.fontSize||40,lines;do{ctx.font=`${l.weight||700} ${size}px Figtree, sans-serif`;lines=wrapText(ctx,l.text,Math.max(1,w-2*pad));const wordsFit=l.text.split(/\s+/).every(word=>ctx.measureText(word).width<=Math.max(1,w-2*pad));if((lines.length*size*1.13<=h-2*pad&&wordsFit)||size<=4)break;size--;}while(size>=4);return {size,lines,pad,lineHeight:size*1.13};}
