$('textContent').onchange=ev=>updateProp(l=>{l.text=ev.target.value.slice(0,3000);arrangeOutput(current())});$('textColor').onchange=ev=>updateProp(l=>l.color=ev.target.value);$('fontSize').onchange=ev=>{const n=Number(ev.target.value);if(Number.isFinite(n))updateProp(l=>l.fontSize=clamp(n,8,500),true)};$('fontWeight').onchange=ev=>{const weight=Number(ev.target.value);if([300,400,500,600,700,800,900].includes(weight))updateProp(l=>{l.weight=weight;arrangeOutput(current())})};$('textAlign').onchange=ev=>updateProp(l=>l.align=ev.target.value);$('fillColor').onchange=ev=>updateProp(l=>l.fill=ev.target.value);$('imageFit').onchange=ev=>updateProp(l=>l.fit=ev.target.value);$('applyContent').onclick=()=>{const l=selected();if(!l||l.locked||l.hidden)return;checkpoint();const values={};for(const k of ['text','color','fill','align','fit','weight','cornerRadius'])if(k in l)values[k]=l[k];for(const o of outputs){const match=o.layers.find(x=>x.id===l.id);if(match){Object.assign(match,values);arrangeOutput(o)}}const source=sources.find(x=>x.id===l.id);if(source)Object.assign(source,values);refresh();toast('Conteúdo aplicado. Os ajustes manuais foram preservados.');};$('sendBack').onclick=()=>moveLayer(-1);$('bringFront').onclick=()=>moveLayer(1);$('deleteLayer').onclick=()=>{if(!selected())return;checkpoint();current().layers=current().layers.filter(l=>l.id!==selectedId);selectedId=null;arrangeOutput(current());refresh()};$('stage').onpointerdown=stageDown;$('stage').onpointermove=stageMove;$('stage').onpointerup=finishDrag;$('stage').onpointercancel=finishDrag;$('stage').onlostpointercapture=finishDrag;$('stage').onkeydown=ev=>{const layers=selectedLayers();if(!layers.length)return;const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[ev.key];if(delta){ev.preventDefault();checkpoint();for(const l of layers){l.manualLayout=true;l.x+=delta[0]*(ev.shiftKey?10:1)/current().w;l.y+=delta[1]*(ev.shiftKey?10:1)/current().h;}renderEditor()}if(ev.key==='Delete'){checkpoint();const ids=layers.map(l=>l.id);current().layers=current().layers.filter(l=>!ids.includes(l.id));selectLayer(null);arrangeOutput(current());refresh()}};window.addEventListener('resize',()=>{if(!$('editor').hidden)sizeStage()});window.addEventListener('beforeunload',ev=>{if(globalThis.SplitProjects?SplitProjects.needsUnloadWarning():sources.length){ev.preventDefault();ev.returnValue=''}});

refresh();ensureFonts().then(()=>{for(const out of outputs)arrangeOutput(out);refresh()}).catch(e=>toast(e.message));
